<script lang="ts">
  import { goto } from '$app/navigation';
  import { onMount } from 'svelte';

  export let view = 'graph';

  type NodeKind = 'fact' | 'signal' | 'axis' | 'decision' | 'interaction';
  type TraceNode = { id: string; label: string; detail: string; kind: NodeKind; x: number; y: number; value?: number; source?: string };
  type TraceEdge = { from: string; to: string; label: string; weight: number; tone: 'supports' | 'weakens' | 'conflicts' | 'conditions' | 'overrides' };

  // PROTOTYPE: one AssessmentTrace projected three ways; the UI never recomputes these values.
  const nodes: TraceNode[] = [
    { id: 'day', label: 'Ngày Ất Mùi', detail: 'Dữ kiện lịch ngày', kind: 'fact', x: 110, y: 110, value: 0.72, source: 'calendar_snapshot' },
    { id: 'truc', label: 'Trực Thành', detail: 'Thế hoàn tất và định hình', kind: 'signal', x: 110, y: 270, value: 0.64, source: 'truc_rule_v1' },
    { id: 'clash', label: 'Xung Mùi–Sửu', detail: 'Quan hệ cần xét theo bối cảnh', kind: 'fact', x: 110, y: 430, value: -0.55, source: 'clash_rule_v2' },
    { id: 'day-axis', label: 'Trục Ngày', detail: 'Generic day quality', kind: 'axis', x: 440, y: 180, value: 0.68 },
    { id: 'personal-axis', label: 'Trục Cá nhân', detail: 'Personal alignment', kind: 'axis', x: 440, y: 390, value: -0.55 },
    { id: 'interaction', label: 'Tương tác Mùi × Sửu', detail: 'Interaction summary', kind: 'interaction', x: 440, y: 545, value: -0.32, source: 'interaction.personal_clash' },
    { id: 'decision', label: 'Day Assessment', detail: 'Chờ mục đích để kết luận', kind: 'decision', x: 790, y: 285, value: 0.31 },
  ];

  const edges: TraceEdge[] = [
    { from: 'day', to: 'day-axis', label: 'supports', weight: 0.72, tone: 'supports' },
    { from: 'truc', to: 'day-axis', label: 'supports', weight: 0.64, tone: 'supports' },
    { from: 'clash', to: 'personal-axis', label: 'weakens', weight: -0.55, tone: 'weakens' },
    { from: 'clash', to: 'interaction', label: 'conditions', weight: 1, tone: 'conditions' },
    { from: 'interaction', to: 'personal-axis', label: 'conflicts', weight: -0.32, tone: 'conflicts' },
    { from: 'day-axis', to: 'decision', label: 'conditions', weight: 0.7, tone: 'conditions' },
    { from: 'personal-axis', to: 'decision', label: 'conditions', weight: -0.55, tone: 'conditions' },
  ];

  const axes = [
    { axis: 'Trục Ngày', verdict: 'contextual_support', subtotal: 0.68, weight: 0.6, contributors: [{ name: 'Ngày Ất Mùi', value: 0.72 }, { name: 'Trực Thành', value: 0.64 }] },
    { axis: 'Trục Cá nhân', verdict: 'unavailable_without_profile', subtotal: -0.55, weight: 0.4, contributors: [{ name: 'Xung Mùi–Sửu', value: -0.55 }, { name: 'Hồ sơ sinh', value: null }] },
  ];

  const colors: Record<NodeKind, string> = { fact: '#8aa0ad', signal: '#d3a34b', axis: '#62a77b', decision: '#df7861', interaction: '#b18ad1' };
  let selectedId = 'decision';

  $: activeNode = nodes.find((node) => node.id === selectedId) ?? nodes[nodes.length - 1];
  $: activeIncoming = edges.filter((edge) => edge.to === selectedId);
  $: activeOutgoing = edges.filter((edge) => edge.from === selectedId);

  function selectNode(id: string) { selectedId = selectedId === id ? 'decision' : id; }
  function setView(next: string) {
    const url = new URL(window.location.href);
    url.searchParams.set('prototype', 'influence');
    url.searchParams.set('view', next);
    goto(`${url.pathname}${url.search}`, { replaceState: true, keepFocus: true, noScroll: true });
  }
  function node(id: string) { return nodes.find((item) => item.id === id)!; }
  function toneColor(tone: TraceEdge['tone']) { return { supports: '#62a77b', weakens: '#d3a34b', conflicts: '#df7861', conditions: '#8aa0ad', overrides: '#ef5e4a' }[tone]; }
  function edgePath(edge: TraceEdge) {
    const from = node(edge.from); const to = node(edge.to); const bend = (to.x - from.x) * 0.45;
    return `M ${from.x + 78} ${from.y} C ${from.x + 78 + bend} ${from.y}, ${to.x - 78 - bend} ${to.y}, ${to.x - 78} ${to.y}`;
  }
  function onKey(event: KeyboardEvent) {
    if (event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement) return;
    if (event.key === '1') setView('graph');
    if (event.key === '2') setView('matrix');
    if (event.key === '3') setView('path');
  }
  onMount(() => { window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey); });
</script>

<svelte:head><title>Influence Explorer — prototype</title></svelte:head>

<div class="explorer">
  <header class="topbar"><div class="wordmark">ÂM LỊCH <span>INFLUENCE EXPLORER</span></div><div class="anchor"><small>DAY VIEW · 19.09.2026</small><b>Ngày Ất Mùi</b><span>09 tháng 08 · 09:42 · Ẩn danh</span></div><div class="prototype-badge">PROTOTYPE · TRACE VIEW</div></header>
  <div class="toolbar"><div><p>ASSESSMENT TRACE</p><h1>Vì sao kết quả trông như vậy?</h1></div><div class="view-tabs"><button class:active={view === 'graph'} onclick={() => setView('graph')}>01 · Influence Graph</button><button class:active={view === 'matrix'} onclick={() => setView('matrix')}>02 · Contribution Matrix</button><button class:active={view === 'path'} onclick={() => setView('path')}>03 · Evidence Path</button></div></div>

  {#if view === 'matrix'}
    <main class="matrix-layout"><section class="matrix-main"><div class="section-label">VECTOR CONTRIBUTIONS</div><h2>Trục nào nhận ảnh hưởng từ yếu tố nào?</h2><p class="muted">Giá trị là contribution đã được core tính toán; dấu âm/dương không phải nhãn tốt/xấu phổ quát.</p><table><thead><tr><th>Yếu tố / interaction</th>{#each axes as axis}<th>{axis.axis}<small>weight {axis.weight}</small></th>{/each}<th>Nguồn</th></tr></thead><tbody>{#each [{ name: 'Ngày Ất Mùi', values: [0.72, null], source: 'calendar_snapshot' }, { name: 'Trực Thành', values: [0.64, null], source: 'truc_rule_v1' }, { name: 'Xung Mùi–Sửu', values: [null, -0.55], source: 'clash_rule_v2' }, { name: 'Mùi × Sửu', values: [null, -0.32], source: 'interaction.personal_clash' }] as row}<tr class:selected={row.name === activeNode.label} onclick={() => selectNode(nodes.find((item) => item.label === row.name)?.id ?? 'decision')}><th>{row.name}</th>{#each row.values as value}<td class:positive={value !== null && value > 0} class:negative={value !== null && value < 0}>{value === null ? '—' : `${value > 0 ? '+' : ''}${value.toFixed(2)}`}</td>{/each}<td><code>{row.source}</code></td></tr>{/each}</tbody></table><div class="subtotal-row">{#each axes as axis}<div><span>{axis.axis} subtotal</span><b class:negative={axis.subtotal < 0}>{axis.subtotal > 0 ? '+' : ''}{axis.subtotal.toFixed(2)}</b></div>{/each}</div></section>{@render DetailsPanel(activeNode, activeIncoming, activeOutgoing)}</main>
  {:else if view === 'path'}
    <main class="path-layout"><section class="path-main"><div class="section-label">EXPLANATION PATH</div><h2>Result → Reason → Evidence</h2><p class="muted">Một đường truy nguyên có thể kiểm tra được, không phải một danh sách citation rời rạc.</p><div class="path-stack"><button class="path-card decision" onclick={() => selectNode('decision')}><span>RESULT</span><b>Day Assessment</b><small>Chờ mục đích để tạo kết luận phù hợp</small></button><i>↓ conditions</i><button class="path-card axis" onclick={() => selectNode('day-axis')}><span>REASON · AXIS</span><b>Trục Ngày · +0.68</b><small>2 yếu tố đóng góp tích cực vào tổng phụ</small></button><i>↓ contributors</i><div class="path-branch"><button class="path-card fact" onclick={() => selectNode('day')}><span>FACT</span><b>Ngày Ất Mùi</b><small>+0.72 · calendar_snapshot</small></button><button class="path-card signal" onclick={() => selectNode('truc')}><span>SIGNAL</span><b>Trực Thành</b><small>+0.64 · truc_rule_v1</small></button></div><i>↓ provenance</i><button class="path-card evidence" onclick={() => selectNode('day')}><span>EVIDENCE</span><b>Rule + source + review state</b><small>Đã duyệt · policy v1.10 · mở bản ghi nguồn →</small></button></div></section>{@render DetailsPanel(activeNode, activeIncoming, activeOutgoing)}</main>
  {:else}
    <main class="graph-layout"><section class="graph-main"><div class="graph-head"><div><div class="section-label">SEMANTIC GRAPH · 7 NODES · 7 EDGES</div><h2>Influence Graph</h2><p class="muted">Mũi tên là quan hệ semantic. Độ dày là magnitude của contribution.</p></div><div class="legend">{#each Object.entries(colors) as [kind, color]}<span><i style={`background:${color}`}></i>{kind}</span>{/each}</div></div><div class="canvas"><svg viewBox="0 0 950 620" role="img" aria-label="Influence graph"><defs>{#each ['supports','weakens','conflicts','conditions','overrides'] as tone}<marker id={`arrow-${tone}`} viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill={toneColor(tone as TraceEdge['tone'])} /></marker>{/each}</defs><g class="edges">{#each edges as edge}<path d={edgePath(edge)} stroke={toneColor(edge.tone)} stroke-width={Math.max(1.5, Math.abs(edge.weight) * 4)} stroke-opacity={selectedId === edge.from || selectedId === edge.to ? 1 : .35} marker-end={`url(#arrow-${edge.tone})`} fill="none"/><text x={(node(edge.from).x + node(edge.to).x) / 2} y={(node(edge.from).y + node(edge.to).y) / 2 - 8} fill={toneColor(edge.tone)}>{edge.label} · {edge.weight > 0 ? '+' : ''}{edge.weight.toFixed(2)}</text>{/each}</g><g class="nodes">{#each nodes as item}<g class="node" class:selected={item.id === selectedId} tabindex="0" role="button" aria-label={item.label} transform={`translate(${item.x - 78},${item.y - 30})`} onclick={() => selectNode(item.id)} onkeydown={(event) => event.key === 'Enter' && selectNode(item.id)}><rect width="156" height="60" rx="7" fill="#202923" stroke={colors[item.kind]} stroke-width={item.id === selectedId ? 3 : 1.5}/><text x="12" y="24" fill="#f4f1e8" class="node-label">{item.label}</text><text x="12" y="43" fill="#9ca9a0" class="node-detail">{item.detail}</text>{#if item.value !== undefined}<text x="145" y="15" text-anchor="end" fill={item.value < 0 ? '#df7861' : '#8bc49a'} class="node-value">{item.value > 0 ? '+' : ''}{item.value.toFixed(2)}</text>{/if}</g>{/each}</g></svg></div></section>{@render DetailsPanel(activeNode, activeIncoming, activeOutgoing)}</main>
  {/if}

  <nav class="bottom-switcher"><button onclick={() => setView('graph')} class:current={view === 'graph'}>1</button><button onclick={() => setView('matrix')} class:current={view === 'matrix'}>2</button><button onclick={() => setView('path')} class:current={view === 'path'}>3</button><span>Graph · Matrix · Path</span><small>1 / 2 / 3</small></nav>
</div>

{#snippet DetailsPanel(activeNode: TraceNode, activeIncoming: TraceEdge[], activeOutgoing: TraceEdge[])}
  <aside class="details"><div class="section-label">SELECTED NODE</div><div class="selected-type" style={`color:${colors[activeNode.kind]}`}>{activeNode.kind}</div><h2>{activeNode.label}</h2><p>{activeNode.detail}</p>{#if activeNode.value !== undefined}<div class="selected-value" class:negative={activeNode.value < 0}><span>contribution / subtotal</span><b>{activeNode.value > 0 ? '+' : ''}{activeNode.value.toFixed(2)}</b></div>{/if}<div class="connections"><div><small>INCOMING</small>{#each activeIncoming as edge}<button onclick={() => selectNode(edge.from)}><i style={`background:${toneColor(edge.tone)}`}></i>{edge.label}<b>{edge.weight > 0 ? '+' : ''}{edge.weight.toFixed(2)}</b></button>{:else}<span class="empty">Không có cạnh vào.</span>{/each}</div><div><small>OUTGOING</small>{#each activeOutgoing as edge}<button onclick={() => selectNode(edge.to)}><i style={`background:${toneColor(edge.tone)}`}></i>{edge.label}<b>{edge.weight > 0 ? '+' : ''}{edge.weight.toFixed(2)}</b></button>{:else}<span class="empty">Không có cạnh ra.</span>{/each}</div></div>{#if activeNode.source}<div class="provenance"><small>PROVENANCE</small><code>{activeNode.source}</code><span>Policy v1.10 · review state: approved</span></div>{/if}<button class="open-source">Mở evidence record ↗</button></aside>
{/snippet}

<style>
  :global(body){margin:0}.explorer{min-height:100%;background:#151b17;color:#e9eee7;font-family:system-ui,sans-serif}.topbar{display:grid;grid-template-columns:250px 1fr 250px;align-items:center;height:74px;padding:0 28px;border-bottom:1px solid #36423a;background:#101511}.wordmark{color:#edc15f;font:700 16px ui-monospace,monospace;letter-spacing:.13em}.wordmark span{display:block;margin-top:5px;color:#7e8b81;font-size:8px;letter-spacing:.18em}.anchor{text-align:center}.anchor small,.anchor b,.anchor span{display:block}.anchor small{color:#7e8b81;font:8px ui-monospace,monospace;letter-spacing:.12em}.anchor b{margin:4px 0;font:17px Georgia,serif}.anchor span{color:#9ba69e;font-size:10px}.prototype-badge{justify-self:end;padding:6px 9px;border:1px solid #77533b;color:#e29a76;font:8px ui-monospace,monospace;letter-spacing:.08em}.toolbar{display:flex;justify-content:space-between;align-items:end;padding:30px 32px 22px;border-bottom:1px solid #36423a}.toolbar h1{margin:0;font:26px Georgia,serif}.toolbar p,.section-label{margin:0 0 8px;color:#829087;font:8px ui-monospace,monospace;letter-spacing:.15em}.view-tabs{display:flex;gap:6px}.view-tabs button{padding:9px 11px;border:1px solid #3f4d43;background:transparent;color:#98a69b;font:9px ui-monospace,monospace;cursor:pointer}.view-tabs button.active{border-color:#edc15f;background:#edc15f;color:#172018}.graph-layout,.matrix-layout,.path-layout{display:grid;grid-template-columns:minmax(650px,1fr) 300px;min-height:calc(100vh - 158px)}.graph-main,.matrix-main,.path-main{padding:28px 32px 100px}.graph-head{display:flex;justify-content:space-between;align-items:start}.graph-head h2,.matrix-main h2,.path-main h2{margin:0;font:23px Georgia,serif}.muted{max-width:680px;margin:7px 0;color:#99a59d;font-size:11px;line-height:1.5}.legend{display:flex;gap:10px;color:#89968d;font:8px ui-monospace,monospace}.legend i{display:inline-block;width:7px;height:7px;margin-right:4px;border-radius:50%}.canvas{margin-top:22px;border:1px solid #344137;background:#19221c;overflow:auto}.canvas svg{display:block;width:100%;min-width:800px;height:auto}.edges text{font:9px ui-monospace,monospace}.node{cursor:pointer;outline:none}.node:hover rect,.node:focus rect{filter:brightness(1.2)}.node-label{font:12px system-ui,sans-serif}.node-detail{font:9px system-ui,sans-serif}.node-value{font:10px ui-monospace,monospace}.details{padding:28px 20px 100px;border-left:1px solid #36423a;background:#111712}.selected-type{font:8px ui-monospace,monospace;text-transform:uppercase;letter-spacing:.14em}.details h2{margin:7px 0;font:22px Georgia,serif}.details>p{margin:0;color:#a2ada5;font-size:11px;line-height:1.4}.selected-value{display:flex;justify-content:space-between;align-items:center;margin:20px 0;padding:12px;border:1px solid #3e5144;background:#1e2a21}.selected-value span{color:#829087;font:8px ui-monospace,monospace}.selected-value b{color:#8bc49a;font:20px ui-monospace,monospace}.selected-value.negative b{color:#df7861}.connections{border-top:1px solid #36423a}.connections>div{padding:14px 0;border-bottom:1px solid #36423a}.connections small,.provenance small{display:block;color:#829087;font:8px ui-monospace,monospace;letter-spacing:.12em}.connections button{display:grid;grid-template-columns:8px 1fr auto;gap:7px;align-items:center;width:100%;padding:8px 0;border:0;background:transparent;color:#dce4dd;text-align:left;font-size:10px;cursor:pointer}.connections button i{width:6px;height:6px;border-radius:50%}.connections button b{font:9px ui-monospace,monospace}.empty{display:block;margin-top:8px;color:#68756c;font-size:10px}.provenance{margin-top:16px;padding-top:15px;border-top:1px solid #36423a}.provenance code{display:block;margin-top:7px;color:#edc15f;font:10px ui-monospace,monospace;word-break:break-word}.provenance span{display:block;margin-top:6px;color:#849087;font-size:9px}.open-source{margin-top:18px;padding:9px 0;border:0;background:transparent;color:#edc15f;font:9px ui-monospace,monospace;cursor:pointer}.matrix-main table{width:100%;margin-top:24px;border-collapse:collapse;font-size:10px}.matrix-main th,.matrix-main td{padding:13px 12px;border:1px solid #36423a;text-align:left}.matrix-main thead th{color:#a8b2aa;font:9px ui-monospace,monospace;background:#1b251e}.matrix-main thead small{display:block;margin-top:5px;color:#718077;font-size:8px;font-weight:normal}.matrix-main tbody th{font-weight:500}.matrix-main tbody tr{cursor:pointer}.matrix-main tbody tr:hover,.matrix-main tbody tr.selected{background:#26342a}.matrix-main td{color:#93a099;font:13px ui-monospace,monospace}.matrix-main td.positive{color:#8bc49a}.matrix-main td.negative{color:#df7861}.matrix-main code{color:#819087;font-size:8px}.subtotal-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px}.subtotal-row div{display:flex;justify-content:space-between;padding:12px;background:#1e2a21;color:#98a69b;font:9px ui-monospace,monospace}.subtotal-row b{color:#8bc49a;font-size:15px}.subtotal-row b.negative{color:#df7861}.path-main{max-width:850px}.path-stack{max-width:620px;margin:28px auto}.path-card{display:block;width:100%;padding:17px;border:1px solid #415046;background:#1e2a21;color:#e8eee9;text-align:left;cursor:pointer}.path-card:hover{border-color:#edc15f}.path-card span,.path-card b,.path-card small{display:block}.path-card span{color:#829087;font:8px ui-monospace,monospace;letter-spacing:.12em}.path-card b{margin:7px 0 4px;font:16px Georgia,serif}.path-card small{color:#9ba69e;font-size:10px}.path-card.decision{border-left:3px solid #df7861}.path-card.axis{border-left:3px solid #62a77b}.path-card.fact{border-left:3px solid #8aa0ad}.path-card.signal{border-left:3px solid #d3a34b}.path-card.evidence{border-left:3px solid #b18ad1}.path-stack>i{display:block;padding:8px 0;color:#829087;text-align:center;font:9px ui-monospace,monospace;font-style:normal}.path-branch{display:grid;grid-template-columns:1fr 1fr;gap:10px}.bottom-switcher{position:fixed;z-index:10;bottom:16px;left:50%;display:flex;gap:5px;align-items:center;padding:6px;border:1px solid #536157;border-radius:999px;background:#101511;box-shadow:0 10px 30px #0b0f0c;color:#9ba69e;transform:translateX(-50%);font:9px ui-monospace,monospace}.bottom-switcher button{width:25px;height:25px;border:0;border-radius:50%;background:#27342b;color:#b3c0b5;cursor:pointer}.bottom-switcher button.current{background:#edc15f;color:#172018}.bottom-switcher span{padding:0 8px}.bottom-switcher small{padding-right:7px;color:#718077}@media(max-width:900px){.graph-layout,.matrix-layout,.path-layout{grid-template-columns:1fr}.details{display:none}.toolbar{display:block}.view-tabs{margin-top:18px;flex-wrap:wrap}.topbar{grid-template-columns:1fr auto}.anchor{display:none}}
</style>
